import re,sys,unicodedata
def norm(s):
    s=unicodedata.normalize('NFC',s)
    for a in '“”″': s=s.replace(a,'"')
    for a in '‘’': s=s.replace(a,"'")
    s=re.sub(r'-\s*\d+\s*-','',s)
    s=re.sub(r'\s+',' ',s).strip()
    return s
